import { concatBytes, encodeUtf8, toHex, uint32ToBigEndian, xorInto } from './bytes.mjs';
import { hmacSha1 } from './hmac.mjs';

export const DEFAULT_ITERATIONS = 1000;

export function pbkdf2HmacSha1(passwordBytes, saltBytes, iterations = DEFAULT_ITERATIONS, keyLength = 16) {
  if (!Number.isInteger(iterations) || iterations <= 0) {
    throw new RangeError('iterations must be a positive integer');
  }

  if (!Number.isInteger(keyLength) || keyLength < 0) {
    throw new RangeError('keyLength must be a non-negative integer');
  }

  if (keyLength === 0) {
    return new Uint8Array(0);
  }

  const blockCount = Math.ceil(keyLength / 20);
  const derivedKey = new Uint8Array(blockCount * 20);
  let offset = 0;

  for (let blockIndex = 1; blockIndex <= blockCount; blockIndex += 1) {
    let u = hmacSha1(passwordBytes, concatBytes([saltBytes, uint32ToBigEndian(blockIndex)]));
    const block = new Uint8Array(u);

    for (let iteration = 1; iteration < iterations; iteration += 1) {
      u = hmacSha1(passwordBytes, u);
      xorInto(block, u);
    }

    derivedKey.set(block, offset);
    offset += block.length;
  }

  return derivedKey.subarray(0, keyLength);
}

export function deriveKeyBytes(passphrase, salt, keyLength = 16, iterations = DEFAULT_ITERATIONS) {
  return pbkdf2HmacSha1(
    encodeUtf8(passphrase),
    encodeUtf8(salt),
    iterations,
    keyLength,
  );
}

export function deriveKeyHex(passphrase, salt, keyLength = 16, iterations = DEFAULT_ITERATIONS) {
  return toHex(deriveKeyBytes(passphrase, salt, keyLength, iterations));
}

