  const blockCount = Math.ceil(keyLength / 20);
  const derivedKey = new Uint8Array(blockCount * 20);
  let offset = 0;

  for (let blockIndex = 1; blockIndex <= blockCount; blockIndex += 1) {
    let u = hmacSha1(passwordBytes, concatBytes([saltBytes, uint32ToBigEndian(blockIndex)]));
