import { bytesToHex, encodeUtf8, int32be, xorInto } from './encoding.mjs';
import { hmacSha1, SHA1_DIGEST_LENGTH } from './hmac.mjs';

export const DEFAULT_ITERATIONS = 1000;
export const DEFAULT_KEY_LENGTH = 16;

export function derivePbkdf2Key(
  password,
  salt,
  keyLength = DEFAULT_KEY_LENGTH,
  iterations = DEFAULT_ITERATIONS,
) {
  const passwordBytes = encodeUtf8(password);
  const saltBytes = encodeUtf8(salt);
  const blockCount = Math.ceil(keyLength / SHA1_DIGEST_LENGTH);
  const derivedKey = Buffer.alloc(blockCount * SHA1_DIGEST_LENGTH);

  for (let blockIndex = 1; blockIndex <= blockCount; blockIndex += 1) {
    const initialBlock = Buffer.concat([saltBytes, int32be(blockIndex)]);
    let u = hmacSha1(passwordBytes, initialBlock);
    const accumulator = Buffer.from(u);

    for (let iteration = 1; iteration < iterations; iteration += 1) {
      u = hmacSha1(passwordBytes, u);
      xorInto(accumulator, u);
    }

    accumulator.copy(derivedKey, (blockIndex - 1) * SHA1_DIGEST_LENGTH);
  }

  return derivedKey.subarray(0, keyLength);
}

export function derivePbkdf2Hex(
  password,
  salt,
  keyLength = DEFAULT_KEY_LENGTH,
  iterations = DEFAULT_ITERATIONS,
) {
  return bytesToHex(derivePbkdf2Key(password, salt, keyLength, iterations));
}

